namespace DocSummary.Models;

public class SummaryRequest
{
    public required string DocumentText { get; set; }
}

namespace DocSummary.Models;

public class SummaryResponse
{
    public required string Summary { get; set; }
}

namespace DocSummary.Services;

public interface ISummaryService
{
    string Summarize(string documentText);
}

namespace DocSummary.Services;

/// <summary>
/// Produces a concise extractive summary by selecting the most important sentences.
/// </summary>
public class ExtractiveSummaryService : ISummaryService
{
    private const int MaxSummarySentences = 3;

    public string Summarize(string documentText)
    {
        if (string.IsNullOrWhiteSpace(documentText))
            return string.Empty;

        var sentences = SplitIntoSentences(documentText);

        if (sentences.Length <= MaxSummarySentences)
            return string.Join(" ", sentences);

        // Score sentences by word frequency relevance
        var wordFrequencies = ComputeWordFrequencies(sentences);
        var scored = sentences
            .Select((s, i) => (Sentence: s, Score: ScoreSentence(s, wordFrequencies), Index: i))
            .OrderByDescending(x => x.Score)
            .Take(MaxSummarySentences)
            .OrderBy(x => x.Index)
            .Select(x => x.Sentence);

        return string.Join(" ", scored);
    }

    private static string[] SplitIntoSentences(string text)
    {
        return text.Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                   .Where(s => s.Length > 0)
                   .Select(s => s + ".")
                   .ToArray();
    }

    private static Dictionary<string, int> ComputeWordFrequencies(string[] sentences)
    {
        var frequencies = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var sentence in sentences)
        {
            foreach (var word in GetWords(sentence))
            {
                frequencies.TryGetValue(word, out int count);
                frequencies[word] = count + 1;
            }
        }
        return frequencies;
    }

    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
    {
        var words = GetWords(sentence);
        if (words.Length == 0) return 0;
        return words.Sum(w => wordFrequencies.GetValueOrDefault(w, 0)) / (double)words.Length;
    }

    private static string[] GetWords(string text)
    {
        return text.Split([' ', ',', ';', ':', '"', '\'', '(', ')', '[', ']', '\n', '\r', '\t'],
                          StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                   .Select(w => w.ToLowerInvariant())
                   .Where(w => w.Length > 2)
                   .ToArray();
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly ISummaryService _summaryService;

    public SummaryController(ISummaryService summaryService)
    {
        _summaryService = summaryService;
    }

    [HttpPost]
    public ActionResult<SummaryResponse> Summarize([FromBody] SummaryRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest("DocumentText must not be empty.");

        var summary = _summaryService.Summarize(request.DocumentText);
        return Ok(new SummaryResponse { Summary = summary });
    }
}

